const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const def = grpc.loadPackageDefinition(protoLoader.loadSync('orders.proto'));
const server = new grpc.Server();
server.addService(def.orders.OrderService.service, {
  placeOrder: (call, callback) => {                       // coarse operation
    const order = createOrder(call.request.customer, call.request.lines);
    callback(null, toConfirmation(order, price(order)));  // plain object payload
  },
});
server.bindAsync('0.0.0.0:50051', grpc.ServerCredentials.createInsecure(), () => server.start());
